head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > dataDragSelectAutoScroll]<br/>dataDragSelect=true 일때 마우스로 Drag 하여 다중 Cell 선택 시 자동 스크롤 기능을 활성화합니다.",
    "validation" : [
        "useShiftKey=true 이고, dataDragDrop, dataDragDropSelf, dataDragDropOther, dataDragDropCell 속성이 모두 false 인 경우에 동작합니다.",
        "true 설정 시, 마우스로 Drag 하여 다중 Cell 선택 시 자동으로 스크롤됩니다.",
        "마우스 Drag 를 유지한 상태로 GridView 영역 밖으로 일정 거리를 이동하면 자동 스크롤이 동작합니다.",
        "false 설정 시, 마우스로 Drag 하여 다중 Cell 선택 시 자동으로 스크롤되지 않습니다.",
        "미설정 시, 마우스로 Drag 하여 다중 Cell 선택 시 자동으로 스크롤되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof target1 !== 'undefined') { target1.remove(); }
    if (typeof dlt_src !== 'undefined') { $p.data.remove("dlt_src"); }

    // con 셀렉트값 : '' 미설정 / 'true' / 'false'
    //  - dataDragSelectAutoScroll 은 dataDragSelect=true + useShiftKey=true +
    //    dataDragDrop/Self/Other/Cell 모두 false 일 때만 동작
    //    → target1 에 dataDragDrop 계열은 부여하지 않음(모두 기본 false)
    let vAutoScroll = con_dataDragSelectAutoScroll.getText();

    // 사용법 안내 라벨 (target 생성 전 가장 먼저 생성)
    //  dataDragSelect, useShiftKey 는 자동 스크롤 동작 전제이므로 둘 다 true 로 고정(con 미제공)
    let lblAutoScroll = (vAutoScroll === '') ? '미설정(기본 false)' : vAutoScroll;
    $c.gcm.createLabel('label="con(dataDragSelectAutoScroll=' + lblAutoScroll + ') 적용, dataDragSelect=true / useShiftKey=true 고정. 자동 스크롤은 dataDragSelect=true + useShiftKey=true + dataDragSelectAutoScroll=true 일 때 동작합니다. 검증 절차 → Body Cell 을 마우스로 Drag 한 채 GridView 영역(하단) 밖으로 일정 거리 이동하여 유지하면 자동으로 세로 스크롤이 동작합니다. [스크롤 위치 출력] 으로 적용값·스크롤 발생 여부(true/false)·scrollTop 을 확인하세요(true 면 발생=true, false/미설정이면 발생=false)."', '', 'label1');

    let strNameSpace = $c.gcm.getNameSpace();

    // === DataList(dlt_src) : 4 Column [text, text, text, text] / 30행 (뷰포트보다 많게) ===
    let strSrc = '';
    strSrc += '<w2:dataList ' + strNameSpace + ' id="dlt_src" baseNode="list" repeatNode="map">';
    strSrc += '<w2:columnInfo>';
    strSrc += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strSrc += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strSrc += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strSrc += '<w2:column id="col4" name="col4" dataType="text"></w2:column>';
    strSrc += '</w2:columnInfo>';
    strSrc += '<w2:data use="true"></w2:data>';
    strSrc += '</w2:dataList>';
    $p.data.create(strSrc);

    // 데이터 30행 로드 (grid height 보다 많은 행 → 세로 스크롤 발생)
    let srcData = [];
    for (let i = 1; i <= 30; i++) {
        srcData.push({ "col1": "행" + i, "col2": (i * 100) + "", "col3": "C" + i, "col4": (i * 10) + "" });
    }
    dlt_src.setJSON(srcData, false);

    let grp_comp = $c.gcm.getTestGroup();

    // === target1 : dataDragSelect/useShiftKey 는 true 고정(전제), dataDragSelectAutoScroll 만 con 값 적용('' 이면 속성 미부여) ===
    //  - dataDragDrop 계열은 전부 미부여(기본 false) → 자동 스크롤 동작 전제 충족
    let props = { dataList: "data:dlt_src", dataDragSelect: true, useShiftKey: true };
    if (vAutoScroll === 'true') { props.dataDragSelectAutoScroll  = true; } else if (vAutoScroll === 'false') { props.dataDragSelectAutoScroll  = false; }
    let srcCList = $c.gcm.createCList(props);

    let strTarget1 = '';
    strTarget1 += '<w2:gridView ' + strNameSpace + ' ' + srcCList + ' id="" style="width:440px;height:150px;">';
    strTarget1 += '<w2:caption style="" id="caption1" value="target1 (dataDragSelectAutoScroll 테스트)"></w2:caption>';
    strTarget1 += '<w2:header style="" id="header1">';
    strTarget1 += '<w2:row style="" id="hrow1">';
    strTarget1 += '<w2:column width="100" style="" inputType="text" id="hcol1" value="col1"></w2:column>';
    strTarget1 += '<w2:column width="100" style="" inputType="text" id="hcol2" value="col2"></w2:column>';
    strTarget1 += '<w2:column width="100" style="" inputType="text" id="hcol3" value="col3"></w2:column>';
    strTarget1 += '<w2:column width="100" style="" inputType="text" id="hcol4" value="col4"></w2:column>';
    strTarget1 += '</w2:row>';
    strTarget1 += '</w2:header>';
    strTarget1 += '<w2:gBody style="" id="gBody1">';
    strTarget1 += '<w2:row style="" id="brow1">';
    strTarget1 += '<w2:column width="100" style="" inputType="text" dataType="text" id="col1" dataList="col1"></w2:column>';
    strTarget1 += '<w2:column width="100" style="" inputType="text" dataType="text" id="col2" dataList="col2"></w2:column>';
    strTarget1 += '<w2:column width="100" style="" inputType="text" dataType="text" id="col3" dataList="col3"></w2:column>';
    strTarget1 += '<w2:column width="100" style="" inputType="text" dataType="text" id="col4" dataList="col4"></w2:column>';
    strTarget1 += '</w2:row>';
    strTarget1 += '</w2:gBody>';
    strTarget1 += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget1, grp_comp);
};



// 스크롤 위치 출력 : 자동 스크롤로 세로 스크롤 위치가 이동했음을 데이터로 확인
//  - GridView 의 세로 스크롤 컨테이너 DOM(id + "_scrollY_div") 의 scrollTop(px)
//  - Drag 전 0 → Drag 로 영역 밖 이동(자동 스크롤) 후 값 증가로 V2(자동으로 스크롤됨) 검증
//  - '스크롤 발생 여부'(scrollTop>0)는 값 비결정성과 무관한 이진 결과 → TSQA 자동화 단정용
scwin.btn_scrollPos_onclick = function () {
    let b = wf_body_bottom.getObj("scwin");
    let div = document.querySelector("[id$='target1_scrollY_div']");
    let top = div ? Math.round(div.scrollTop) : -1;
    b.setReturnValue("적용된 dataDragSelectAutoScroll : " + target1.options.dataDragSelectAutoScroll);
    b.setReturnValue("스크롤 발생 여부 : " + (top > 0));
    b.setReturnValue("현재 세로 스크롤 위치(scrollTop) : " + top + "px");
};
